  if(!enabled||!physical.getFeatures().shaderFloat64)throw std::invalid_argument("Double96 GPU requires shaderFloat64 enabled on the logical device");
  const auto properties=physical.getProperties2<vk::PhysicalDeviceProperties2,vk::PhysicalDeviceFloatControlsProperties>();const auto& controls=properties.get<vk::PhysicalDeviceFloatControlsProperties>();if(!controls.shaderRoundingModeRTEFloat64||!controls.shaderSignedZeroInfNanPreserveFloat64)throw std::invalid_argument("Double96 GPU requires RTE64 and SignedZeroInfNanPreserve64");
