  if(!mutual.empty()){if(projection.empty()||mutual.size()<5||mutual[0]!=0x07230203u)throw std::invalid_argument("Double96 mutual shader requires projection and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{mutual.begin(),mutual.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!neighbor.empty()){if(mutual.empty()||neighbor.size()<5||neighbor[0]!=0x07230203u)throw std::invalid_argument("Double96 neighbor shader requires mutual and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{neighbor.begin(),neighbor.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!pyramid.empty()){if(neighbor.empty()||pyramid.size()<5||pyramid[0]!=0x07230203u)throw std::invalid_argument("Double96 pyramid shader requires neighbor and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{pyramid.begin(),pyramid.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!comparison.empty()){if(pyramid.empty()||comparison.size()<5||comparison[0]!=0x07230203u)throw std::invalid_argument("Double96 comparison shader requires pyramid and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{comparison.begin(),comparison.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!jnd.empty()){if(comparison.empty()||jnd.size()<5||jnd[0]!=0x07230203u)throw std::invalid_argument("Double96 JND shader requires comparison and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{jnd.begin(),jnd.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!csf.empty()){if(jnd.empty()||csf.size()<5||csf[0]!=0x07230203u)throw std::invalid_argument("Double96 CSF shader requires JND and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{csf.begin(),csf.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
  if(!quality.empty()){if(csf.empty()||quality.size()<5||quality[0]!=0x07230203u)throw std::invalid_argument("Double96 quality shader requires CSF and valid SPIR-V");modules.push_back(VulkanRuntime::createShaderModule(device,{quality.begin(),quality.end()}));pipelines.push_back(VulkanRuntime::createComputePipeline(device,modules.back(),layout));}
