std::vector<double> SRGBQuality96GPUDouble::logarithms(std::span<const double> values){std::lock_guard lock(impl_->mutex);return impl_->logarithms(values);}
SRGBQuality96GPUDouble::SRGBQuality96GPUDouble(const vk::raii::PhysicalDevice& p,const vk::raii::Device& d,const vk::raii::Queue& q,uint32_t family,bool enabled,const Shaders& shaders,std::span<const uint32_t> projection,std::span<const uint32_t> mutual,std::span<const uint32_t> neighbor,std::span<const uint32_t> pyramid,std::span<const uint32_t> comparison,std::span<const uint32_t> jnd,std::span<const uint32_t> csf,std::span<const uint32_t> quality,std::span<const uint32_t> logarithm):impl_(std::make_unique<Impl>(p,d,q,family,enabled,shaders,projection,mutual,neighbor,pyramid,comparison,jnd,csf,quality,logarithm)){}
SRGBQuality96GPUDouble::~SRGBQuality96GPUDouble()=default;
SRGBQuality96GPUDouble::Convolution SRGBQuality96GPUDouble::convolve(std::span<const double> padded,std::span<const double> coefficients,bool traces){validate(padded,36864);validate(coefficients,36864);std::lock_guard lock(impl_->mutex);auto& g=*impl_;std::vector<double> input;input.reserve(73728);for(double v:padded){input.push_back(v);input.push_back(0.);}upload(g.buffers[0],input);upload(g.filter,coefficients);g.begin();const unsigned groups[]{6,7,576,6,12,144};for(unsigned i=0;i<6;++i)g.dispatch(i,i,{192,(i==0||i==3)?192u:1u,0,0},groups[i]);g.finish();Convolution result;result.cropped=download(g.buffers[6],9216,true);if(traces){result.inverse=download(g.buffers[5],36864,true);result.spectrum=download(g.buffers[2],73728,false);}return result;}
std::vector<double> SRGBQuality96GPUDouble::base_fft(std::span<const double> input){validate(input,288);std::lock_guard lock(impl_->mutex);auto& g=*impl_;upload(g.buffers[0],input);g.begin();for(unsigned i=0;i<3;++i)g.dispatch(6,i==2?6:i,{i,1,0,0},1);g.finish();return download(g.buffers[2],288,false);}
RGBOpticalResponseDouble SRGBQuality96GPUDouble::project(std::span<const double> optical,const RGBSpectralSamples& spectral){validate(optical,27648);const auto calibration=calibrate_rgb_spectral_age(spectral,24);std::vector<double> coefficients;for(const auto& channel:calibration.matrix)coefficients.insert(coefficients.end(),channel.begin(),channel.end());std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<8)throw std::runtime_error("Double96 GPU projection shader not configured");upload(g.buffers[0],optical);upload(g.filter,coefficients);g.begin();g.dispatch(7,7,{0,0,0,0},144);g.finish();auto values=download(g.projectionOutput,82944,false);RGBOpticalResponseDouble result;result.response.assign(values.begin(),values.begin()+36864);result.clamped.assign(values.begin()+36864,values.begin()+73728);result.adaptation_input.assign(values.begin()+73728,values.end());for(double v:result.adaptation_input)result.adaptation_log.push_back(std::log(std::max(v,1e-6)));return result;}
std::vector<double> SRGBQuality96GPUDouble::mutual(std::span<const double> reference,std::span<const double> test,unsigned w,unsigned h){if(h!=w||(w!=96&&w!=48&&w!=24&&w!=12))throw std::invalid_argument("Double96 mutual band geometry");validate(reference,size_t(w)*h);validate(test,reference.size());std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<9)throw std::runtime_error("Double96 mutual GPU shader not configured");upload(g.buffers[0],reference);upload(g.filter,test);g.begin();g.dispatch(8,0,{w,h,0,0},(w*h+63)/64);g.finish();return download(g.buffers[1],reference.size(),false);}std::vector<double> SRGBQuality96GPUDouble::neighbor(std::span<const std::vector<double>> masks,unsigned band){const unsigned widths[]{96,96,48,24,12};if(masks.size()!=5||band>=5)throw std::invalid_argument("Double96 neighbor requires5bands");for(size_t b=0;b<5;++b){validate(masks[b],size_t(widths[b])*widths[b]);for(double v:masks[b])if(v<0)throw std::invalid_argument("Double96 neighbor masks must be nonnegative");}std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<10)throw std::runtime_error("Double96 neighbor GPU shader not configured");unsigned w=widths[band];g.begin();g.dispatch(9,2,{w,w,w,3},(w*w+63)/64);g.finish();
 auto add=[&](unsigned b){unsigned n=widths[b];if(n==w){upload(g.buffers[2],masks[b]);g.begin();}else{auto plan=make_resize_axis_plan(int(n),int(w));std::vector<double> coefficients{double(plan.taps)};for(double v:plan.normalization){if(v!=1.)throw std::runtime_error("Double96 neighbor normalization profile mismatch");coefficients.push_back(v);}for(size_t i=0;i<plan.weights.size();++i){coefficients.push_back(double(plan.indices[i]));coefficients.push_back(plan.weights[i]);}upload(g.buffers[0],masks[b]);upload(g.filter,coefficients);g.begin();g.dispatch(9,0,{n,n,w,0},(n*w+63)/64);g.dispatch(9,1,{w,n,w,1},(w*w+63)/64);}g.dispatch(9,2,{w,w,w,2},(w*w+63)/64);g.finish();};if(band>0)add(band-1);if(band<3)add(band+1);return download(g.buffers[3],size_t(w)*w,false);}SP0PyramidDouble SRGBQuality96GPUDouble::pyramid(std::span<const double> response){validate(response,9216);std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<11)throw std::runtime_error("Double96 pyramid GPU shader not configured");const auto filters=create_sp0_model_double();upload(g.buffers[0],response);auto correlate=[&](unsigned descriptor,unsigned w,const std::vector<double>& filter,unsigned k,unsigned step,unsigned exponent){upload(g.filter,filter);g.begin();unsigned output=(w+step-1)/step;g.dispatch(10,descriptor,{w,k,step,exponent},(output*output+63)/64);g.finish();};SP0PyramidDouble result;correlate(0,96,filters.high,9,1,0);result.bands.push_back({96,96,download(g.buffers[1],9216,false)});correlate(0,96,filters.lo0,7,1,0);unsigned w=96;for(unsigned level=0;level<3;++level){unsigned descriptor=level+1;correlate(descriptor,w,filters.orientation,9,1,level+1);result.bands.push_back({w,w,download(g.buffers[descriptor+1],size_t(w)*w,false)});correlate(descriptor,w,filters.lo,13,2,level==2?4:0);w/=2;}result.base_pre=download(g.buffers[4],144,false);g.begin();g.dispatch(10,4,{12,0,0,16},1);g.finish();auto base=download(g.buffers[5],145,false);result.base_mean=base.back();base.pop_back();result.bands.push_back({12,12,std::move(base)});return result;}std::vector<double> SRGBQuality96GPUDouble::comparison(std::span<const double> reference,std::span<const double> test,unsigned band){if(band>=5)throw std::invalid_argument("Double96 comparison band");validate(reference,27648);validate(test,27648);for(size_t i=0;i<reference.size();++i)if(reference[i]<0||test[i]<0)throw std::invalid_argument("Double96 comparison requires nonnegative RGB");std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<12)throw std::runtime_error("Double96 comparison GPU shader not configured");upload(g.buffers[0],reference);upload(g.filter,test);g.begin();g.dispatch(11,0,{0,0,0,0},144);g.finish();unsigned w=band<2?96:96/(1u<<(band-1));if(w==96)return download(g.buffers[1],9216,false);auto plan=make_resize_axis_plan(96,int(w));std::vector<double> coefficients{double(plan.taps)};for(double v:plan.normalization){if(v!=1.)throw std::runtime_error("Double96 comparison normalization profile mismatch");coefficients.push_back(v);}for(size_t i=0;i<plan.weights.size();++i){coefficients.push_back(double(plan.indices[i]));coefficients.push_back(plan.weights[i]);}upload(g.filter,coefficients);g.begin();g.dispatch(9,1,{96,96,w,0},(96*w+63)/64);g.dispatch(9,2,{w,96,w,1},(w*w+63)/64);g.finish();return download(g.buffers[3],size_t(w)*w,false);}RGBJNDResponseDouble SRGBQuality96GPUDouble::jnd(const JNDLUT& lut,std::span<const double> lmsr,std::span<const double> adaptation){static_assert(JND_LUT_SIZE==2048);validate(lmsr,36864);validate(adaptation,9216);for(double v:lmsr)if(v<=0)throw std::invalid_argument("Double96 JND requires positive LMSR");for(double v:adaptation)if(v<=0)throw std::invalid_argument("Double96 JND requires positive adaptation");for(size_t i=0;i<JND_LUT_SIZE;++i)if(!std::isfinite(lut.log_luminance[i])||!std::isfinite(lut.cone[i])||!std::isfinite(lut.rod[i])||(i&&lut.log_luminance[i]<=lut.log_luminance[i-1]))throw std::invalid_argument("Invalid Double96 JND table");RGBJNDResponseDouble result;std::lock_guard lock(impl_->mutex);auto& g=*impl_;const bool gpuLog=g.pipelines.size()>=16;std::vector<double> adaptationLogs;if(gpuLog)adaptationLogs=g.logarithms(adaptation);double sum=0;for(unsigned x=0;x<96;++x)for(unsigned y=0;y<96;++y)sum+=gpuLog?adaptationLogs[2*(y*96+x)]:std::log(adaptation[y*96+x]);result.geometric_mean=std::exp(sum/9216.);result.pupil_reduction=pupil_luminance_reduction(result.geometric_mean,96.*96./30./30.,24);if(g.pipelines.size()<13)throw std::runtime_error("Double96 JND GPU shader not configured");upload(g.buffers[0],lmsr);std::vector<double> pupil{result.pupil_reduction};upload(g.filter,pupil);g.begin();g.dispatch(12,0,{0,0,0,0},576);g.finish();result.post_pupil=download(g.buffers[1],36864,false);validate(result.post_pupil,36864);const double low=std::pow(10.,lut.log_luminance.front()),high=std::pow(10.,lut.log_luminance.back());std::vector<double> queries(27648);for(size_t c=0;c<3;++c)for(size_t i=0;i<9216;++i)queries[c*9216+i]=std::clamp(result.post_pupil[(c==2?3:c)*9216+i],low,high);if(gpuLog){const auto logs=g.logarithms(queries);for(size_t i=0;i<queries.size();++i)queries[i]=logs[2*i+1];}else{for(double& query:queries)query=std::log10(query);}validate(queries,27648);std::vector<double> coefficients;for(const auto* table:{&lut.log_luminance,&lut.cone,&lut.rod})coefficients.insert(coefficients.end(),table->begin(),table->end());for(const auto* table:{&lut.cone,&lut.rod}){for(size_t i=0;i<JND_LUT_SIZE-1;++i)coefficients.push_back(((*table)[i+1]-(*table)[i])/(lut.log_luminance[i+1]-lut.log_luminance[i]));coefficients.push_back(0.);}validate(coefficients,5*JND_LUT_SIZE);upload(g.buffers[0],queries);upload(g.filter,coefficients);g.begin();g.dispatch(12,0,{1,0,0,0},144);g.finish();auto values=download(g.buffers[1],46080,false);result.channels.assign(values.begin(),values.begin()+36864);result.response.assign(values.begin()+36864,values.end());return result;}QualityCSFDouble SRGBQuality96GPUDouble::csf(std::span<const double> mean_log,unsigned band,double base_frequency){validate(mean_log,9216);if(band>=5||!std::isfinite(base_frequency)||base_frequency<0)throw std::invalid_argument("Double96 CSF band/frequency");QualityCSFDouble result;result.table=create_csf_lut(15./double(1u<<band));const auto grid=csf_log_luminance_grid();std::vector<double> coefficients(grid.begin(),grid.end());coefficients.insert(coefficients.end(),result.table.begin(),result.table.end());for(size_t i=0;i<255;++i)coefficients.push_back((result.table[i+1]-result.table[i])/(grid[i+1]-grid[i]));coefficients.push_back(0.);validate(coefficients,768);std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<14)throw std::runtime_error("Double96 CSF GPU shader not configured");unsigned w=band<2?96:96/(1u<<(band-1)),descriptor=0;upload(g.buffers[0],mean_log);if(w!=96){auto plan=make_resize_axis_plan(96,int(w));std::vector<double> weights{double(plan.taps)};for(double v:plan.normalization){if(v!=1.)throw std::runtime_error("Double96 CSF normalization profile mismatch");weights.push_back(v);}for(size_t i=0;i<plan.weights.size();++i){weights.push_back(double(plan.indices[i]));weights.push_back(plan.weights[i]);}upload(g.filter,weights);g.begin();g.dispatch(9,0,{96,96,w,0},(96*w+63)/64);g.dispatch(9,1,{w,96,w,1},(w*w+63)/64);g.finish();descriptor=2;}upload(g.filter,coefficients);g.begin();g.dispatch(13,descriptor,{w,0,0,0},(w*w+63)/64);if(band==4)g.dispatch(13,descriptor,{w,2,0,0},1);g.finish();size_t n=size_t(w)*w;auto values=download(g.buffers[descriptor+1],3*n+(band==4?1:0),false);result.log_adaptation.assign(values.begin(),values.begin()+n);result.sensitivity.assign(values.begin()+n,values.begin()+2*n);result.noise.assign(values.begin()+2*n,values.begin()+3*n);if(band==4){result.base_luminance=std::pow(10.,values.back());std::vector<double> uniform{1./compute_ncsf(base_frequency,result.base_luminance)};upload(g.filter,uniform);g.begin();g.dispatch(13,descriptor,{w,1,0,0},(w*w+63)/64);g.finish();auto filled=download(g.buffers[descriptor+1],3*n,false);result.noise.assign(filled.begin()+2*n,filled.end());}return result;}QualityBandDouble SRGBQuality96GPUDouble::quality(std::span<const double> difference,std::span<const double> self,std::span<const double> neighbor,std::span<const double> noise,std::span<const double> comparison,unsigned w,unsigned h,std::vector<double>* denominator,double* pooling_sum){if(w!=h||(w!=96&&w!=48&&w!=24&&w!=12))throw std::invalid_argument("Double96 quality band geometry");size_t n=size_t(w)*h;validate(difference,n);validate(self,n);validate(neighbor,n);validate(comparison,n);if(noise.size()!=n)throw std::invalid_argument("Double96 quality noise shape");for(size_t i=0;i<n;++i)if(self[i]<0||neighbor[i]<0||!(noise[i]>0)||std::isnan(noise[i]))throw std::invalid_argument("Invalid Double96 quality input");const auto params=quality_mask_parameters_double();double p=params[0],q=params[1],pf=params[2];std::vector<double> prepared(6*n);for(size_t i=0;i<n;++i){prepared[i]=std::pow(std::abs(self[i]),q);prepared[n+i]=std::pow(std::abs(neighbor[i]),q);prepared[2*n+i]=std::pow(std::abs(difference[i]),p);prepared[3*n+i]=difference[i];prepared[4*n+i]=std::pow(noise[i],2*p);prepared[5*n+i]=comparison[i];}std::vector<double> coefficients{params[3],params[5]*std::pow(0.,q),params[4]};std::lock_guard lock(impl_->mutex);auto& g=*impl_;if(g.pipelines.size()<15)throw std::runtime_error("Double96 quality GPU shader not configured");upload(g.buffers[0],prepared);upload(g.filter,coefficients);g.begin();g.dispatch(14,0,{w,h,0,0},unsigned((n+63)/64));g.finish();auto values=download(g.buffers[1],5*n,false);QualityBandDouble result;result.mask_noise.assign(values.begin(),values.begin()+n);result.excitation.assign(values.begin()+n,values.begin()+2*n);result.difference.assign(values.begin()+2*n,values.begin()+3*n);result.masked.assign(values.begin()+3*n,values.begin()+4*n);if(denominator)denominator->assign(values.begin()+4*n,values.end());std::vector<double> powers(n);result.psychometric.resize(n);for(size_t i=0;i<n;++i){double d=result.difference[i];result.psychometric[i]=(d>0?1.:d<0?-1.:0.)*std::pow(std::abs(d),pf);powers[i]=std::pow(std::abs(result.masked[i]),.8);}upload(g.buffers[0],powers);g.begin();g.dispatch(14,0,{w,h,1,0},1);g.finish();auto sum=download(g.buffers[1],1,false);if(pooling_sum)*pooling_sum=sum[0];result.error=std::pow(sum[0],1./.8);return result;}SRGBQuality96BackendDouble SRGBQuality96GPUDouble::backend(){SRGBQuality96BackendDouble result{[this](auto p,auto f){return convolve(p,f).cropped;},[this](auto v){return base_fft(v);}};if(impl_->pipelines.size()>=8)result.project=[this](auto v,const auto& spectral){return project(v,spectral);};if(impl_->pipelines.size()>=9)result.mutual=[this](auto r,auto t,unsigned w,unsigned h){return mutual(r,t,w,h);};if(impl_->pipelines.size()>=10)result.neighbor=[this](auto masks,unsigned b){return neighbor(masks,b);};if(impl_->pipelines.size()>=11)result.pyramid=[this](auto v){return pyramid(v);};if(impl_->pipelines.size()>=12)result.comparison=[this](auto r,auto t,unsigned b){return comparison(r,t,b);};if(impl_->pipelines.size()>=13)result.jnd=[this](const auto& lut,auto lmsr,auto adaptation){return jnd(lut,lmsr,adaptation);};if(impl_->pipelines.size()>=14)result.csf=[this](auto log,unsigned b,double frequency){return csf(log,b,frequency);};if(impl_->pipelines.size()>=15)result.quality=[this](auto d,auto s,auto neighbor,auto noise,auto comparison,unsigned w,unsigned h){return quality(d,s,neighbor,noise,comparison,w,h);};return result;}
